"""Extract consecutive ranges and singles from index_list.

  Args:
    index_list: List of monotone increasing non-negative integers.
    range_size_limit: Largest size range to return.  If a larger
      consecutive range exists it will be returned as multiple
      ranges.

  Returns:
   ranges, singles where ranges is a list of [first, last] pairs of
     consecutive elements in index_list, and singles is all of the
     other elements, in original order.
  """
def extract_ranges(index_list: Any, range_size_limit: Any = 32) -> object {
    if not index_list {
        return ([], []);
    }
    first = index_list[0];
    last = first;
    ranges = [];
    singles = [];
    for i in index_list[1:] {
        if ((i == (last + 1)) and ((last - first) <= range_size_limit)) {
            last = i;
        } else {
            if (last > first) {
                ranges.append([first, last]);
            } else {
                singles.append(first);
            }
            first = i;
            last = i;
        }
    }
    if (last > first) {
        ranges.append([first, last]);
    } else {
        singles.append(first);
    }
    return (ranges, singles);
}

"""
    Minimum remaining length (for sequential, parallel cut detection)

    Parameters
    --------------
    traces
        Traces
    """
def get_min_remaining_length(traces: Any) -> object {
    min_len_traces = [];
    min_rem_length = [];
    for x in traces {
        if (len(x) == 0) {
            min_len_traces.append(0);
        } else {
            min_len_traces.append(len(x[0]));
        }
        min_rem_length.append(0);
    }
    min_rem_length[-1] = 0;
    min_rem_length[-2] = min_len_traces[-1];
    j = len(traces) - 3;
    while (j >= 0) {
        min_rem_length[j] = min_rem_length[(j + 1)] + min_len_traces[(j + 1)];
        j = j - 1;
    }
    return (min_len_traces, min_rem_length);
}

"""
    Remove a single extension from a file name, if present.
    """
def strip_extension(name: str) -> str {
    last_dot = name.rfind(".");
    if (last_dot > -1) {
        return name[:last_dot];
    } else {
        return name;
    }
}

